    44	export function resolveCanonicalRuntimeProjectRoot(searchOrigin: string): string {
    45	  const fallback = resolve(searchOrigin);
    46	  const cached = canonicalRuntimeProjectRootCache.get(fallback);
    47	  if (cached !== undefined) return cached;
    48	  try {
    49	    const inventory = execFileSync('git', ['worktree', 'list', '--porcelain', '-z'], {
    50	      cwd: fallback,
    51	      encoding: 'utf8',
    52	      timeout: 2_000,
    53	      stdio: ['ignore', 'pipe', 'ignore'],
    54	    });
    55	    const primary = inventory
    56	      .split('\0')
    57	      .find(field => field.startsWith('worktree '))
    58	      ?.slice('worktree '.length)
    59	      .trim();
    60	    if (primary) {
    61	      const resolved = resolve(primary);
    62	      canonicalRuntimeProjectRootCache.set(fallback, resolved);
    63	      return resolved;
    64	    }
    65	  } catch {
    66	    // Non-git or incomplete layouts retain the caller-provided project root.
    67	  }
    68	  // Deliberately NOT cached: see the note above -- a transient failure must not
    69	  // pin the fallback for the process lifetime.
    70	  return fallback;
