   458	 * Conservative source classifier used by the contract smoke. Any production
   459	 * file that imports a provider adapter, is itself an adapter, or combines a
   460	 * child-process API with provider vocabulary must have an explicit inventory
   461	 * row. False positives are classified, never silently excluded, so adding a
   462	 * new direct provider spawn in a new file makes the contract fail closed.
   463	 */
   464	export function isProviderExecutionSurfaceCandidate(relativePath: string, source: string): boolean {
   465	  if (!relativePath.endsWith('.ts')) return false;
   466	  if (/(?:^|\/)(?:tasks|tests|generated)(?:\/|$)/.test(relativePath)) return false;
   467	  if (relativePath === 'core/provider-process-registry.ts') return false;
   468	  if (/^providers\/(?:codex-cli|claude-cli|gemini-cli)\.ts$/.test(relativePath)) return true;
   469	  if (/providers\/(?:codex-cli|claude-cli|gemini-cli)\.js/.test(source)) return true;
   470	  if (/\brunHostRun\s*\(/.test(source)) return true;
   471	  // B-137a: strip documentation filename references before the provider-word
   472	  // scan. The words are matched case-insensitively, so a prose citation of
   473	  // "CLAUDE.md" (the project convention doc, referenced by many core modules)
   474	  // read as a provider reference: any file that both used child_process for git
   475	  // and cited that doc became an "unclassified provider execution surface".
   476	  // scope-contract.ts tripped exactly this way on a comment citing the handler
   477	  // convention -- a docs citation, not a provider workload. Several already
   478	  // inventoried files (audit-scan, audit-trigger, rollout-check,
   479	  // runtime-environment-checks) match for the same non-reason. Stripping only
   480	  // "<provider>.md" filenames keeps every real provider reference intact,
   481	  // including CLAUDE_CLI, claudeCli, 'claude' and providers/claude-cli.js.
   482	  const withoutDocReferences = source.replace(/\b(?:codex|claude|agy|gemini|antigravity)\.md\b/gi, '');
   483	  // B-137a: the provider word no longer requires a trailing \b. The old
   484	  // /\bclaude\b/i missed identifier forms entirely -- `claudeCli`, `CLAUDE_CLI`,
   485	  // `codexRunner` all failed to match, because \b does not break between two
   486	  // word characters or before `_`. A file spawning a provider through such an
   487	  // identifier was therefore invisible to this tripwire (verified against the
   488	  // pre-change regex). A leading boundary is kept so unrelated substrings do not
   489	  // match, but the tail is now open so identifier and member forms are caught.
   490	  return /node:child_process/.test(source)
   491	    && /\b(?:codex|claude|agy|gemini|antigravity)/i.test(withoutDocReferences);
